NAME = 'FinSTLK2017: Pyhä Raamattu (STLK 2017)'
BOOK = 'I Corinthians'

CHAPTERS = {
    1: {
        1: 'Paavali, Kristuksen Jeesuksen kutsuttu apostoli Jumalan tahdosta, ja veli Soostenes',
        2: 'Korinttossa olevalle Jumalan seurakunnalle, Kristuksessa Jeesuksessa pyhitetyille, kutsutuille pyhille, sekä kaikille, jotka huutavat avuksi Herramme Jeesuksen Kristuksen nimeä kaikissa paikkakunnissa, niin omissaan kuin meidänkin.',
        3: 'Armo teille ja rauha Jumalalta, Isältämme, ja Herralta Jeesukselta Kristukselta!',
        4: 'Kiitän Jumalaani aina teidän tähtenne siitä Jumalan armosta, joka on annettu teille Kristuksessa Jeesuksessa,',
        5: 'että kaikessa olette rikastuneet hänessä, kaikessa sanassa ja kaikessa tiedossa,',
        6: 'sen mukaan kuin todistus Kristuksesta on vahvistettu teissä,',
        7: 'niin ettei teiltä puutu mitään missään armolahjassa teidän odottaessanne Herramme Jeesuksen Kristuksen ilmestymistä.',
        8: 'Hän on myös vahvistava teitä loppuun asti, niin että olette nuhteettomat meidän Herramme Jeesuksen Kristuksen päivänä.',
        9: 'Jumala on uskollinen, hän, jonka kautta olette kutsutut hänen Poikansa Jeesuksen Kristuksen, meidän Herramme yhteyteen.',
        10: 'Mutta kehotan teitä, veljet, meidän Herramme Jeesuksen Kristuksen nimeen, että kaikki olisitte puheessa yksimieliset, ettei keskuudessanne olisi eriseuroja, vaan että teillä olisi täysin sama mieli ja sama ajatus.',
        11: 'Sillä Kloen perheväeltä olen saanut kuulla teistä, veljeni, että teillä on riitoja keskuudessanne.',
        12: 'Tarkoitan sitä, että itse kukin teistä sanoo: "minä olen Paavalin", "minä Apolloksen", "minä Keefaan" tai: "minä Kristuksen".',
        13: 'Onko Kristus jaettu? Eihän Paavalia ole ristiinnaulittu teidän edestänne? Vai oletteko te kastetut Paavalin nimeen?',
        14: 'Kiitän Jumalaa, etten ole kastanut teistä ketään paitsi Krispuksen ja Gaiuksen,',
        15: 'niin ettei kukaan sanoisi, että te olette minun nimeeni kastetut.',
        16: 'Kastoinhan myös Stefanaan perhekunnan. Sitten en tiedä, olenko ketään muuta kastanut.',
        17: 'Sillä Kristus ei lähettänyt minua kastamaan, vaan evankeliumia julistamaan – ei puheen viisaudella, ettei Kristuksen risti menisi mitättömäksi.',
        18: 'Sillä sana rististä on hullutus niille, jotka kadotukseen joutuvat, mutta meille, jotka pelastumme, se on Jumalan voima.',
        19: 'Onhan kirjoitettu: "Hävitän viisaiden viisauden, ja hylkään ymmärtävien ymmärryksen."',
        20: 'Missä on viisas? Missä kirjanoppinut? Missä tämän maailman tutkija? Eikö Jumala ole tehnyt maailman viisautta hullutukseksi?',
        21: 'Sillä koska maailma ei oppinut Jumalan viisaudesta viisauden avulla tuntemaan Jumalaa, Jumala näki hyväksi hullun saarnan kautta pelastaa ne, jotka uskovat,',
        22: 'koskapa juutalaiset vaativat merkkiä ja kreikkalaiset etsivät viisautta,',
        23: 'me taas saarnaamme ristiinnaulittua Kristusta, joka on juutalaisille pahennus ja pakanoille hulluutta,',
        24: 'mutta joka niille, jotka ovat kutsutut, olkoot juutalaisia tai kreikkalaisia, on Kristus, Jumalan voima ja Jumalan viisaus.',
        25: 'Sillä Jumalan hulluus on viisaampi kuin ihmiset, ja Jumalan heikkous on väkevämpi kuin ihmiset.',
        26: 'Sillä katsokaa, veljet, omaa kutsumistanne: ei ole monta viisasta lihan mukaan, ei monta vaikutusvaltaista, ei monta jalosukuista,',
        27: 'vaan sen, mikä on hulluutta maailmalle, sen Jumala valitsi saattaakseen viisaat häpeään, ja sen, mikä on heikkoa maailmassa, Jumala valitsi saattaakseen häpeään sen, mikä on vaikutusvaltaista,',
        28: 'ja sen, mikä maailmassa on halpasukuista ja halveksittua, Jumala valitsi, sen, joka ei ole mitään, tehdäkseen mitättömäksi sen, joka jotakin on,',
        29: 'ettei mikään liha kerskuisi Jumalan edessä.',
        30: 'Mutta hänestä on teidän olemisenne Kristuksessa Jeesuksessa, joka on tullut meille viisaudeksi Jumalalta, vanhurskaudeksi, pyhitykseksi ja lunastukseksi,',
        31: 'että kävisi, kuten on kirjoitettu: "Se, joka kerskaa, kerskatkoon Herrassa."',
    },
    2: {
        1: 'Tullessani luoksenne, veljet, en tullut suurenmoisella puheella tai viisaudella teille Jumalan todistusta julistamaan.',
        2: 'Sillä olin päättänyt olla luonanne tuntematta mitään muuta paitsi Jeesuksen Kristuksen, ja hänet ristiinnaulittuna.',
        3: 'Ja olin luonanne heikkoudessa, pelossa ja vapisin kovin,',
        4: 'eikä puheeni ja saarnani ollut kiehtovia viisauden sanoja, vaan Hengen ja voiman osoittamista,',
        5: 'ettei uskonne olisi ihmisten viisaudessa, vaan Jumalan voimassa.',
        6: 'Kuitenkin puhumme viisautta täydellisten seurassa, mutta emme tämän maailmanajan viisautta emmekä tämän maailman valtiaiden, jotka kukistuvat,',
        7: 'vaan puhumme salattua Jumalan viisautta, sitä kätkettyä, jonka Jumala on edeltämäärännyt ennen maailmanaikoja meidän kirkkaudeksemme,',
        8: 'sitä, jota kukaan tämän maailman valtiaista ei ole tuntenut – sillä jos he olisivat sen tunteneet, he eivät olisi kirkkauden Herraa ristiinnaulinneet –',
        9: 'vaan kuten on kirjoitettu: "mitä silmä ei ole nähnyt eikä korva kuullut, mikä ei ole ihmisen sydämeen noussut ja minkä Jumala on valmistanut niille, jotka häntä rakastavat."',
        10: 'Mutta meille Jumala on sen ilmoittanut Henkensä kautta, sillä Henki tutkii kaiken, Jumalan syvyydetkin.',
        11: 'Sillä kuka ihmisistä tietää, mitä ihmisessä on, paitsi ihmisen henki, joka hänessä on? Samoin ei myöskään kukaan tiedä, mitä Jumalassa on, paitsi Jumalan Henki.',
        12: 'Mutta me emme ole saaneet maailman henkeä, vaan sen Hengen, joka on Jumalasta, että tietäisimme, mitä Jumala on meille lahjoittanut.',
        13: 'Sitä myös puhumme, emme inhimillisen viisauden opettamilla sanoilla, vaan Pyhän Hengen opettamilla, selittäen hengelliset hengellisesti.',
        14: 'Mutta luonnollinen ihminen ei ota vastaan sitä, mikä Jumalan Hengen on. Sillä se on hänelle hulluutta, eikä hän voi sitä ymmärtää, koska sitä on tutkittava hengellisesti.',
        15: 'Hengellinen ihminen sitä vastoin tutkii kaiken, mutta häntä itseään ei tutki kukaan.',
        16: 'Sillä: "kuka on tullut tuntemaan Herran mielen, että voisi häntä opettaa?" Mutta meillä on Kristuksen mieli.',
    },
    3: {
        1: 'Niinpä, veljet, minä en voinut puhua teille kuin hengellisille, vaan kuin lihallisille, kuin pienille lapsille Kristuksessa.',
        2: 'Maitoa juotin teille, en antanut ruokaa, sillä sitä ette silloin kestäneet, ettekä vielä nytkään kestä,',
        3: 'olettehan vielä lihallisia. Sillä kun keskuudessanne on kateutta, riitaa ja erimielisyyttä, ettekö silloin ole lihallisia ja vaella ihmisten tavoin?',
        4: 'Kun yksi sanoo: "minä olen Paavalin", ja toinen: "minä olen Apollon", ettekö silloin ole lihallisia?',
        5: 'Mikä Paavali sitten on ja mikä taas Apollo? Palvelijoita, joiden kautta te olette tulleet uskoviksi, palvelijoita sen mukaan, mitä Herra on heille kullekin antanut.',
        6: 'Minä istutin, Apollo kasteli, mutta Jumala on antanut kasvun.',
        7: 'Niin ei siis istuttaja ole mitään, eikä kastelijakaan, vaan Jumala, joka antaa kasvun.',
        8: 'Mutta istuttaja ja kastelija ovat yhtä, kuitenkin kumpikin on saava oman palkkansa oman työnsä mukaan.',
        9: 'Sillä olemme Jumalan työtovereita. Olette Jumalan viljapelto, Jumalan rakennus.',
        10: 'Sen Jumalan armon mukaan, joka on minulle annettu, olen viisaan rakentajan tavoin pannut perustuksen, mutta toinen sille rakentaa. Kuitenkin jokainen katsokoon, kuinka hän sille rakentaa.',
        11: 'Sillä muuta perustusta ei kukaan voi panna sen tilalle, mikä on pantu, ja se on Jeesus Kristus.',
        12: 'Mutta jos joku rakentaa tälle perustukselle, rakensipa kullasta, hopeasta, jalokivistä, puusta, heinistä tai oljista,',
        13: 'niin kunkin teko on tuleva näkyviin. Sillä sen saattaa ilmi se päivä, joka tulessa ilmestyy, ja tuli koettelee, millainen kunkin teko on.',
        14: 'Jos jonkun sille tekemä rakennus kestää, hän saa palkan.',
        15: 'Mutta jos jonkun tekemä palaa, hän kärsii vahingon. Mutta hän itse pelastuu, kuitenkin kuin tulen läpi.',
        16: 'Ettekö tiedä, että te olette Jumalan temppeli ja että Jumalan Henki asuu teissä?',
        17: 'Jos joku turmelee Jumalan temppelin, Jumala turmelee hänet, sillä Jumalan temppeli on pyhä. Sellaisia te olette.',
        18: 'Älköön kukaan pettäkö itseään. Jos joku joukossanne luulee olevansa viisas tässä maailmassa, tulkoon tyhmäksi, että tulisi viisaaksi.',
        19: 'Sillä tämän maailman viisaus on hullutusta Jumalan edessä. Sillä kirjoitettu on: "Hän vangitsee viisaat heidän viekkauteensa",',
        20: 'ja vielä: "Herra tietää viisasten ajatusten olevan turhia."',
        21: 'Älköön siis kukaan kerskatko ihmisistä, sillä kaikki on teidän,',
        22: 'olkoon Paavali, Apollo, Keefas, maailma, elämä, kuolema, nykyiset tai tulevaiset, kaikki on teidän.',
        23: 'Mutta te olette Kristuksen, ja Kristus on Jumalan.',
    },
    4: {
        1: 'Niin pitäköön jokainen meitä Kristuksen palvelijoina ja Jumalan salaisuuksien huoneenhaltijoina.',
        2: 'Mutta huoneenhaltijoilta edellytetään ennen muuta, että heidät havaitaan uskollisiksi.',
        3: 'Mutta minulle on pikkuasia, että te minua tuomitsette tai jokin ihmisten tuomiopäivä. En minäkään itseäni tuomitse,',
        4: 'sillä minulla ei ole mitään tunnollani, mutta ei minua siitä syystä ole vanhurskaaksi julistettu, vaan minun tuomitsijani on Herra.',
        5: 'Älkää sen tähden lausuko mitään tuomiota, ennen kuin aika on, ennen kuin Herra tulee, joka myös on saattava valoon pimeyden kätköt ja tuova julki sydänten ajatukset. Silloin kukin saa kiitoksensa Jumalalta.',
        6: 'Tämän olen, veljet, sovittanut itseeni ja Apolloon, teidän tähtenne, että meistä oppisitte tämän: "Ei pidä järkeillä yli sen, mikä on kirjoitettu", ettette pöyhkeillen asettuisi mikä minkin puolelle toista vastaan.',
        7: 'Sillä kuka antaa sinulle etusijan? Ja mitä sinulla on, jota et ole saanut lahjaksi? Mutta jos olet sen saanut, niin miksi kerskaat, ikään kuin se ei olisi saatua?',
        8: 'Te olette jo ravitut, teistä on jo tullut rikkaita, ilman meitä teistä on tullut kuninkaita! Kunpa teistä olisikin tullut kuninkaita, niin että mekin tulisimme kuninkaiksi teidän kanssanne!',
        9: 'Sillä minusta näyttää, että Jumala on asettanut meidät apostolit viimeisiksi, ikään kuin kuolemaan tuomituiksi. Meistä on tullut kaiken maailman katseltava, sekä enkelien että ihmisten,',
        10: 'me olemme houkkia Kristuksen tähden, mutta te viisaita Kristuksessa, me olemme heikkoja, mutta te vahvoja. Te olette kunnioitettuja, mutta me halveksittuja.',
        11: 'Yhä edelleen me kärsimme sekä nälkää että janoa, olemme vähissä vaatteissa, meitä ruoskitaan, ja kuljemme kodittomina,',
        12: 'näemme vaivaa tehden työtä omin käsin. Kun meitä panetellaan, siunaamme. Kun meitä vainotaan, kestämme.',
        13: 'Kun meitä pilkataan, puhumme lempeästi. Meistä on tullut kuin maailman tunkio, kaikkien törkykasa, aina tähän asti.',
        14: 'En kirjoita tätä häväistäkseni teitä, vaan kuin rakkaita lapsiani neuvoen.',
        15: 'Sillä vaikka teillä olisi kymmenentuhatta kasvattajaa Kristuksessa, teillä kuitenkaan ei ole monta isää, sillä Kristuksessa Jeesuksessa minä teidät synnytin evankeliumilla.',
        16: 'Kehotan siis teitä: olkaa minun seuraajiani.',
        17: 'Sen vuoksi lähetin teille Timoteuksen, joka on minun rakas ja uskollinen lapseni Herrassa. Hän on muistuttava teitä minun teistäni Kristuksessa Jeesuksessa, sen mukaan kuin kaikkialla, joka seurakunnassa, opetan.',
        18: 'Muutamat teistä ovat paisuneet pöyhkeiksi, niin kuin minä en olisikaan tulossa luoksenne.',
        19: 'Mutta tulen luoksenne pian, jos Herra tahtoo, ja silloin otan selon, en noiden pöyhkeiden sanoista, vaan voimasta.',
        20: 'Sillä Jumalan valtakunta ei ole sanoissa, vaan voimassa.',
        21: 'Kumman tahdotte? Tulenko luoksenne ruoska kädessä vai sävyisyyden hengessä rakkaudessa?',
    },
    5: {
        1: 'Yleensä kuuluu, että keskuudessanne on haureutta, jopa sellaista haureutta, jota ei ole pakanoidenkaan keskuudessa, että eräskin pitää isänsä vaimoa.',
        2: 'Te olette paisuneet pöyhkeiksi! Eikö teidän pikemminkin olisi pitänyt tulla murheellisiksi, että se, joka on tehnyt tuollaisen teon, poistettaisiin keskuudestanne?',
        3: 'Sillä minä, joka tosin ruumiillisesti olen poissa, mutta hengessä kuitenkin läsnä, olen jo kuin läsnä ollen puolestani päättänyt, että se, joka tuollaisen teon on tehnyt, on',
        4: '– sitten kun te ja minun henkeni sekä meidän Herramme Jeesuksen voima, olemme tulleet yhteen –',
        5: 'Herran Jeesuksen nimessä hylättävä saatanan haltuun lihan turmioksi, että hänen henkensä pelastuisi Herran päivänä.',
        6: 'Ei ole hyvä, että kerskaatte. Ettekö tiedä, että vähäinen hapate hapattaa koko taikinan?',
        7: 'Peratkaa pois vanha hapantaikina, että olisitte uusi taikina, niin kuin olettekin happamattomat, sillä onhan meidän pääsiäislampaamme, Kristus, teurastettu.',
        8: 'Viettäkäämme siis juhlaa, ei vanhassa hapantaikinassa eikä ilkeyden ja pahuuden hapantaikinassa, vaan puhtauden ja totuuden happamattomuudessa.',
        9: 'Kirjoitin teille kirjeessäni, ettette seurustelisi huorintekijöiden kanssa.',
        10: 'En tarkoittanut yleensä tämän maailman huorintekijöitä, ahneita, anastajia tai epäjumalanpalvelijoita, sillä silloinhan teidän täytyisi lähteä pois maailmasta.',
        11: 'Vaan minä kirjoitin teille, että jos joku, jota kutsutaan veljeksi, on huorintekijä, ahne, epäjumalanpalvelija, pilkkaaja, juomari tai anastaja, te ette seurustelisi ettekä söisikään sellaisen kanssa.',
        12: 'Sillä onko minun asiani tuomita niitä, jotka ovat ulkopuolella? Ettekö tekin tuomitse vain niitä, jotka ovat sisäpuolella?',
        13: 'Mutta ulkopuolella olevat tuomitsee Jumala. "Poistakaa paha keskuudestanne."',
    },
    6: {
        1: 'Rohkeneeko kukaan teistä, jolla on riita-asia toisen kanssa, käydä oikeutta väärien edessä eikä pyhien edessä?',
        2: 'Vai ettekö tiedä, että pyhät tulevat tuomitsemaan maailman? Jos te tuomitsette maailman, ettekö kelpaa ratkaisemaan aivan vähäpätöisiä asioita?',
        3: 'Ettekö tiedä, että tulemme tuomitsemaan enkeleitä, emmekö sitten maallisia asioita?',
        4: 'Jos teillä siis on maallisia asioita ratkaistavina, nekö te asetatte tuomareiksi, jotka ovat halveksittuja seurakunnassa?',
        5: 'Teidän häpeäksenne tämän sanon. Eikö teidän joukossanne sitten ole ketään viisasta, joka voisi ratkaista veljien välin?',
        6: 'Vaan veli käy oikeutta veljeä vastaan, vieläpä uskosta osattomien edessä!',
        7: 'Teille on jo yleensä vaurioksi, että käräjöitte keskenänne. Miksi ette ennemmin salli tehdä vääryyttä itsellenne? Miksi ette ennemmin anna riistää omaanne?',
        8: 'Sen sijaan te itse teette vääryyttä ja riistätte toisen omaa, vieläpä veljien.',
        9: 'Vai ettekö tiedä, etteivät väärät peri Jumalan valtakuntaa? Älkää eksykö. Eivät huorintekijät, eivät epäjumalanpalvelijat, eivät avionrikkojat, eivät elostelijat eivätkä miehen kanssa makaavat miehet,',
        10: 'eivät varkaat, eivät ahneet, eivät juomarit, eivät pilkkaajat eivätkä rosvot peri Jumalan valtakuntaa.',
        11: 'Tuollaisia tekin olitte, jotkut teistä. Mutta olette vastaanottaneet pesun, olette pyhitetyt, olette vanhurskaiksi julistetut Herramme Jeesuksen Kristuksen nimessä ja Jumalamme Hengessä.',
        12: 'Kaikki on minulle luvallista, mutta kaikki ei ole hyödyksi. Kaikki on minulle luvallista, mutta minä en saa antaa minkään itseäni vallita.',
        13: 'Ruuat ovat vatsaa varten ja vatsa ruokia varten, ja Jumala on tekevä lopun niin toisesta kuin toisestakin. Mutta ruumis ei ole haureutta varten, vaan Herraa varten, ja Herra ruumista varten.',
        14: 'Jumala, joka herätti kuolleista Herran, on herättävä meidätkin voimallaan.',
        15: 'Ettekö tiedä, että teidän ruumiinne ovat Kristuksen jäseniä? Ottaisinko siis Kristuksen jäsenet ja tekisin ne porton jäseniksi? Ei ikinä!',
        16: 'Vai ettekö tiedä, että joka yhtyy porttoon, tulee yhdeksi ruumiiksi hänen kanssaan? Onhan sanottu: "Ne kaksi tulevat yhdeksi lihaksi."',
        17: 'Mutta joka yhtyy Herraan, on yksi henki [hänen kanssaan].',
        18: 'Paetkaa haureutta. Kaikki muu synti, mitä ikinä ihminen tekee, on ruumiin ulkopuolella, mutta haureuden harjoittaja tekee syntiä omaa ruumistaan vastaan.',
        19: 'Vai ettekö tiedä, että teidän ruumiinne on Pyhän Hengen temppeli, joka Henki teissä on ja joka teillä on Jumalalta, ja ettette ole itsenne omat?',
        20: 'Sillä te olette kalliisti ostetut. Kirkastakaa siis Jumala ruumiissanne ja hengessänne, jotka ovat Jumalan.',
    },
    7: {
        1: 'Mutta mitä siihen tulee, mistä minulle kirjoititte, niin hyvä on miehen olla menemättä avioon,',
        2: 'mutta haureuden välttämiseksi olkoon kullakin miehellä oma vaimonsa ja kullakin naisella aviomiehensä.',
        3: 'Täyttäköön mies suosiollisesti aviovelvollisuutensa vaimoaan kohtaan, ja samoin vaimo miestään kohtaan.',
        4: 'Vaimon ruumis ei ole hänen omassa, vaan hänen miehensä vallassa. Samoin ei miehenkään ruumis ole hänen omassa, vaan vaimon vallassa.',
        5: 'Älkää vetäytykö pois toisistanne, paitsi ehkä keskinäisestä sopimuksesta ajaksi, niin että teillä olisi aikaa rukoukseen ja sitten taas tulisitte yhteen, ettei saatana kiusaisi teitä, kun ette voi itseänne hillitä.',
        6: 'Mutta tämän sanon myönnytyksenä, en käskynä.',
        7: 'Haluan kaikkien ihmisten olevan niin kuin minäkin, mutta kullakin on oma armolahjansa Jumalalta, yhdellä näin, toisella noin.',
        8: 'Mutta naimattomille ja leskille sanon: heille on hyvä, jos pysyvät sellaisina kuin minäkin.',
        9: 'Mutta jos eivät voi itseään hillitä, menkööt naimisiin, sillä parempi on avioitua kuin palaa.',
        10: 'Mutta naimisissa oleville julistan, en minä, vaan Herra, ettei vaimo saa erota miehestään.',
        11: 'Mutta jos hän eroaa, pysyköön naimattomana tai sopikoon miehensä kanssa, eikä mies saa hylätä vaimoaan.',
        12: 'Mutta muille sanon minä, ei Herra: jos jollakulla veljellä on vaimo, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, älköön mies hylätkö häntä.',
        13: 'Samoin älköön vaimokaan, jos hänellä on mies, joka ei usko, ja tämä suostuu asumaan hänen kanssaan, hylätkö miestään.',
        14: 'Sillä mies, joka ei usko, on pyhitetty vaimonsa kautta, ja vaimo, joka ei usko, on pyhitetty miehensä kautta. Muutenhan teidän lapsenne olisivat saastaisia, mutta nyt he ovat pyhiä.',
        15: 'Mutta jos se, joka ei usko, eroaa, erotkoon. Veli ja sisar eivät ole sellaisissa tapauksissa orjuutetut, sillä rauhaan on Jumala teidät kutsunut.',
        16: 'Sillä mistä tiedät, vaimo, voitko pelastaa miehesi? Tai mistä tiedät, mies, voitko pelastaa vaimosi?',
        17: 'Vaeltakoon vain kukin sen mukaan, millaisen osan Herra on hänelle antanut, ja siinä asemassa, missä Jumala on hänet kutsunut. Näin säädän kaikissa seurakunnissa.',
        18: 'Jos joku on kutsuttu ympärileikattuna, älköön pyrkikö ympärileikkaamattomaksi. Jos joku on kutsuttu ympärileikkaamattomana, älköön ympärileikkauttako itseään.',
        19: 'Ei ympärileikkaus ole mitään, eikä ympärileikkaamattomuus ole mitään, vaan Jumalan käskyjen pitäminen.',
        20: 'Pysyköön kukin siinä kutsumuksessa, missä hänet on kutsuttu.',
        21: 'Jos olet kutsuttu orjana, älä siitä murehdi. – Mutta jos voit päästä vapaaksi, käytä tilaisuutta ennemmin hyväksesi. –',
        22: 'Sillä se, joka on kutsuttu orjana Herrassa, on Herran vapautettu. Samoin vapaana kutsuttu on Kristuksen orja.',
        23: 'Te olette kalliisti ostetut, älkää olko ihmisten orjia.',
        24: 'Pysyköön kukin, veljet, Jumalan edessä siinä asemassa, missä hänet on kutsuttu.',
        25: 'Mutta neitsyistä minulla ei ole Herran käskyä, vaan lausun mielipiteeni niin kuin se, joka on Herralta saanut sen laupeuden, että hän on luotettava.',
        26: 'Olen siis sitä mieltä, että lähestyvän ahdingon tähden jokaisen on hyvä pysyä siten kuin on.',
        27: 'Jos olet sidottu vaimoon, älä etsi eroa. Jos et ole sidottu vaimoon, älä etsi vaimoa.',
        28: 'Mutta jos menetkin naimisiin, et tee syntiä. Jos neitsyt menee naimisiin, hänkään ei tee syntiä. Mutta ne, jotka niin tekevät, joutuvat kärsimään ruumiillista vaivaa, ja siitä minä tahtoisin teidät säästää.',
        29: 'Mutta sen sanon, veljet: aika on lyhennetty. Olkoot tästedes nekin, joilla on vaimot, kuin heillä ei heitä olisi,',
        30: 'ja ne, jotka itkevät, kuin eivät itkisi, ja ne, jotka iloitsevat, kuin eivät iloitsisi, ja ne, jotka ostavat, kuin eivät omistaisi,',
        31: 'ja ne, jotka tätä maailmaa hyödykseen käyttävät, kuin eivät sitä käyttäisi, sillä tämän maailman olemus on katoamassa.',
        32: 'Haluan, että olisitte vapaita huolista. Naimaton mies huolehtii siitä, mikä on Herran ja kuinka olisi Herralle mieliksi.',
        33: 'Mutta nainut huolehtii ajallisista, kuinka olisi vaimolleen mieliksi.',
        34: 'On eroa vaimon ja neitsyen välillä. Vaimo, jolla ei ole enää miestä, ja neitsyt huolehtivat siitä, mikä on Herran, että olisivat pyhät sekä ruumiin että hengen puolesta. Mutta naimisissa oleva huolehtii ajallisista, kuinka olisi miehelleen mieliksi.',
        35: 'Tämän sanon teidän omaksi hyödyksenne, en heittääkseni ansaa kaulaanne, vaan sitä varten, että eläisitte säädyllisesti ja pysyisitte häiriintymättä Herrassa.',
        36: 'Mutta jos joku arvelee olevansa armoton tytärtään kohtaan, joka on täydessä naimaiässä, ja jos kerran sen pitää tapahtua, niin tehköön, kuten tahtoo. Hän ei tee syntiä. Menkööt naimisiin.',
        37: 'Se taas, joka pysyy sydämessään lujana eikä ole minkään pakon alainen, vaan voi noudattaa omaa tahtoaan ja on sydämessään päättänyt pitää tyttärensä naimattomana, tekee hyvin.',
        38: 'Siis, joka naittaa tyttärensä, tekee hyvin, ja joka ei naita, tekee paremmin.',
        39: 'Vaimo on sidottu lakiin, niin kauan kuin hänen miehensä elää, mutta jos mies nukkuu pois, hän on vapaa menemään naimisiin, kenen kanssa tahtoo, mutta vain Herrassa.',
        40: 'Mutta hän on onnellisempi, jos pysyy sillä tavoin kuin on. Se on minun mielipiteeni, ja luulen, että minullakin on Jumalan Henki.',
    },
    8: {
        1: 'Mitä sitten epäjumalille uhrattuun tulee, tiedämme, että meillä kaikilla on tieto. Tieto paisuttaa, mutta rakkaus rakentaa.',
        2: 'Jos joku luulee jotakin tietävänsä, hän ei vielä tiedä, kuten tulee tietää.',
        3: 'Mutta sen, joka rakastaa Jumalaa, Jumala tuntee.',
        4: 'Mitä nyt epäjumalille uhratun syömiseen tulee, tiedämme, ettei maailmassa ole yhtään epäjumalaa ja ettei ole muuta Jumalaa kuin yksi.',
        5: 'Sillä vaikka onkin niin sanottuja jumalia, olipa heitä sitten taivaassa tai maan päällä, kuten onkin paljon jumalia ja herroja,',
        6: 'meillä on kuitenkin ainoastaan yksi Jumala, Isä, josta kaikki on ja jota varten me olemme, ja yksi Herra, Jeesus Kristus, jonka kautta kaikki on, myös me hänen kauttaan.',
        7: 'Mutta kaikilla ei ole tätä tietoa, vaan epäjumalaan sidotulla omallatunnolla muutamat vielä nytkin syövät uhrilihaa pitäen sitä uhrina epäjumalille, ja heidän heikko omatuntonsa tahraantuu siitä.',
        8: 'Mutta ruoka ei lähennä meitä Jumalaan. Jos syömme, emme siitä hyödy. Jos olemme syömättä, emme siitä vahingoitu.',
        9: 'Katsokaa kuitenkin, ettei tämä valtanne koidu heikoille loukkaukseksi.',
        10: 'Sillä jos joku näkee sinun, jolla on tieto, aterioivan epäjumalan huoneessa, eikö hänen omatuntonsa, kun hän on heikko, vahvistu epäjumalille uhratun syömiseen?',
        11: 'Sinun tietoosi vedoten turmeltuu heikko veli, jonka tähden Kristus on kuollut.',
        12: 'Mutta kun te näin teette syntiä veljiä vastaan ja haavoitatte heidän heikkoa omaatuntoaan, teette syntiä Kristusta vastaan.',
        13: 'Sen tähden, jos ruoka on lankeemukseksi veljelleni, en ikinä enää syö lihaa, etten olisi lankeemukseksi veljelleni.',
    },
    9: {
        1: 'Enkö ole apostoli? Enkö ole vapaa? Enkö ole nähnyt Jeesusta Kristusta, meidän Herraamme? Ettekö te ole minun tekoni Herrassa?',
        2: 'Jos en olekaan apostoli muille, olen ainakin teille, sillä te olette apostolinvirkani sinetti Herrassa.',
        3: 'Tämä on puolustukseni niitä vastaan, jotka asettuvat minua tutkimaan.',
        4: 'Eikö meillä ole oikeus syödä ja juoda?',
        5: 'Eikö meillä ole oikeus kuljettaa mukanamme vaimoa, sisarta, kuten muillakin apostoleilla, Herran veljillä ja Keefaalla?',
        6: 'Vai ainoastaanko minulla ja Barnabaalla ei ole oikeutta olla tekemättä työtä?',
        7: 'Kuka tekee koskaan sotapalvelusta omalla kustannuksellaan? Kuka istuttaa viinitarhan, eikä syö sen hedelmää? Tai kuka kaitsee karjaa, eikä nauti karjansa maitoa?',
        8: 'Puhunko tätä vain ihmisten tavalla? Eikö lakikin sano samaa?',
        9: 'Onhan Mooseksen laissa kirjoitettuna: "Älä sido puivan härän suuta." Eihän Jumala häristä näin huolta pitäne?',
        10: 'Eikö hän sano sitä kaiketikin meidän tähtemme? Meidän tähtemmehän on kirjoitettu, että kyntäjän tulee kyntää toivossa ja puivan puida osansa saamisen toivossa.',
        11: 'Jos me olemme kylväneet teille hengellistä hyvää, onko paljon, jos me niitämme teiltä aineellista?',
        12: 'Jos muilla on teihin tällainen oikeus, eikö paljoa enemmän meillä? Mutta emme ole käyttäneet tätä oikeutta, vaan kestämme kaiken, ettemme panisi mitään estettä Kristuksen evankeliumille.',
        13: 'Ettekö tiedä, että ne, jotka hoitavat pyhäkön toimia, saavat ravintonsa pyhäköstä, ja jotka ovat asetetut uhrialttarin palvelukseen, saavat osansa silloin kuin alttarikin?',
        14: 'Samoin myös Herra on säätänyt, että evankeliumin julistajien tulee saada evankeliumista elatuksensa.',
        15: 'Mutta minä en ole käyttänyt hyväkseni ainoatakaan näistä oikeuksistani. Enkä kirjoitakaan tätä siinä mielessä, että niitä sovitettaisiin minuun, sillä minun olisi parempi mieluummin kuolla, kuin että joku tekisi tyhjäksi kerskaukseni.',
        16: 'Sillä jos julistan evankeliumia, minulla ei ole siitä kerskaamista, minun täytyy se tehdä. Voi minua, ellen evankeliumia julista!',
        17: 'Sillä jos teen sitä halusta, minulla on palkka. Mutta jos en tee sitä halusta, on huoneenhaltijan virka kuitenkin minulle uskottu.',
        18: 'Mikä siis on palkkani? Se, että kun julistan Kristuksen evankeliumia, teen sen ilmaiseksi, niin etten käytä evankeliumin minulle antamaa oikeutta.',
        19: 'Sillä vaikka olen riippumaton kaikista, olen tehnyt itseni kaikkien palvelijaksi voittaakseni niin monta kuin suinkin.',
        20: 'Olen ollut juutalaisille kuin juutalainen voittaakseni juutalaisia, lain alaisille kuin lain alainen voittaakseni lain alaiset,',
        21: 'ilman lakia oleville kuin olisin ilman lakia – vaikka en ole ilman Jumalan lakia, vaan olen Kristuksen laissa – voittaakseni ne, jotka ovat ilman lakia.',
        22: 'Heikoille olen ollut heikko voittaakseni heikot. Kaikille olen ollut kaikkea pelastaakseni edes muutamia.',
        23: 'Mutta kaiken teen evankeliumin tähden, että minäkin tulisin siitä osalliseksi.',
        24: 'Ettekö tiedä, että ne, jotka stadionilla juoksevat, tosin kaikki juoksevat, mutta yksi saa voittopalkinnon? Juoskaa niin kuin se, että sen saavuttaisitte.',
        25: 'Mutta jokainen kilpailija noudattaa itsehillintää kaikessa, he saadakseen katoavan seppeleen, mutta me katoamattoman.',
        26: 'Minä en siis juokse umpimähkään enkä nyrkkeile kuin ilmaan huitoen,',
        27: 'vaan kuritan ruumistani ja orjuutan sitä, etten minä, joka muille saarnaan, itse ehkä joutuisi hylätyksi.',
    },
    10: {
        1: 'En tahdo, veljet, pitää teitä tietämättöminä siitä, että isämme olivat kaikki pilven alla ja kulkivat kaikki meren halki,',
        2: 'saivat kaikki kasteen Moosekseen pilvessä ja meressä,',
        3: 'söivät kaikki samaa hengellistä ruokaa',
        4: 'ja joivat kaikki samaa hengellistä juomaa. Sillä he joivat hengellisestä kalliosta, joka heitä seurasi, ja se kallio oli Kristus.',
        5: 'Mutta useimpiin heistä Jumala ei mieltynyt, koska he saivat surmansa erämaassa.',
        6: 'Tämä tapahtui varoittavaksi esimerkiksi meille, ettemme himoitsisi pahaa, kuten he himoitsivat.',
        7: 'Älkää myöskään olko epäjumalanpalvelijoita kuten muutamat heistä, kuten on kirjoitettu: "Kansa istui syömään ja juomaan, ja he nousivat karkeloimaan."',
        8: 'Älkäämme myöskään harjoittako haureutta, niin kuin muutamat heistä harjoittivat haureutta, ja heitä kaatui yhtenä päivänä kaksikymmentä kolme tuhatta.',
        9: 'Älkäämme myöskään kiusatko Kristusta, niin kuin muutamat heistä kiusasivat ja saivat käärmeiltä surmansa.',
        10: 'Älkääkä napisko, niin kuin muutamat heistä napisivat ja saivat surmansa tuhoojalta.',
        11: 'Mutta kaikki nämä, mitä heille tapahtui, ovat esikuvia, ja ne on kirjoitettu varoitukseksi meille, joille maailmanaikojen loppukausi on tullut.',
        12: 'Sen tähden, joka luulee seisovansa, katsokoon, ettei kaadu.',
        13: 'Teitä ei ole kohdannut muu kuin inhimillinen kiusaus. Mutta Jumala on uskollinen: hän ei salli teitä kiusattavan yli voimienne, vaan kiusauksen ohella hän valmistaa myös pääsyn siitä, että voitte sen kestää.',
        14: 'Sen tähden, rakkaani, paetkaa epäjumalanpalvelusta.',
        15: 'Puhun kuin viisaille. Arvioikaa itse, mitä sanon.',
        16: 'Siunauksen malja, jonka siunaamme, eikö se ole osallisuus Kristuksen vereen? Se leipä, jonka murramme, eikö se ole osallisuus Kristuksen ruumiiseen?',
        17: 'Koska leipä on yksi, me monet olemme yksi ruumis, sillä olemme kaikki yhdestä leivästä osallisia.',
        18: 'Katsokaa Israelia lihan mukaan. Eivätkö ne, jotka syövät uhreja, ole uhrialttarista osallisia?',
        19: 'Mitä siis sanon? Niinkö, että epäjumala on jotakin, tai että epäjumalanuhri on jotakin?',
        20: 'Ei, vaan että sen, mitä pakanat uhraavat, he uhraavat riivaajille eivätkä Jumalalle, mutta minä en tahdo teidän olevan osallisia riivaajista.',
        21: 'Ette voi juoda Herran maljasta ja riivaajien maljasta, ette voi olla osallisia Herran pöydästä ja riivaajien pöydästä.',
        22: 'Vai tahdommeko herättää Herran kiivauden? Emme kaiketi ole häntä vahvempia?',
        23: 'Kaikki on minulle luvallista, mutta ei kaikki ole hyödyksi. Kaikki on minulle luvallista, mutta ei kaikki rakenna.',
        24: 'Älköön kukaan etsikö omaansa, vaan toisen etua.',
        25: 'Syökää kaikkea, mitä lihatorilla myydään, kyselemättä mitään omantunnon tähden,',
        26: 'sillä: "Herran on maa ja kaikki, mitä siinä on."',
        27: 'Jos joku uskosta osaton kutsuu teidät ja haluatte mennä, niin syökää kaikkea, mitä eteenne pannaan, kyselemättä mitään omantunnon tähden.',
        28: 'Mutta jos joku sanoo teille: "Tämä on epäjumalanuhria", älkää syökö sitä hänen tähtensä, joka sen ilmaisi, eikä omantunnon tähden. Maa on Herran ja kaikki, mitä siinä on.',
        29: 'En puhu sinun itsesi omastatunnosta, vaan tuon toisen, sillä miksi toisen omatunto saisi tuomita minun vapauteni?',
        30: 'Jos minä nautin sen kiitoksella, miksi minua pilkataan siitä, mistä minä kiitän?',
        31: 'Söittepä siis tai joitte tai teitte mitä hyvänsä, tehkää kaikki Jumalan kunniaksi.',
        32: 'Älkää olko pahennukseksi juutalaisille, älkää kreikkalaisille älkääkä Jumalan seurakunnalle,',
        33: 'kuten minäkin olen kaikille kaikessa mieliksi enkä etsi omaa hyötyäni, vaan monien hyötyä, että he pelastuisivat.',
    },
    11: {
        1: 'Olkaa minun seuraajiani, kuten minäkin olen Kristuksen seuraaja.',
        2: 'Kiitän teitä, että muistatte minua kaikessa ja pidätte kiinni opetuksistani sellaisina, kuin olen ne teille antanut.',
        3: 'Mutta tahdon teidän tietävän, että Kristus on jokaisen miehen pää ja että mies on vaimon pää ja että Jumala on Kristuksen pää.',
        4: 'Jokainen mies, joka rukoilee tai profetoi pää peitettynä, häpäisee päänsä.',
        5: 'Mutta jokainen vaimo, joka rukoilee tai profetoi pää peittämättömänä, häpäisee päänsä, sillä se on aivan sama, kuin jos hänen päänsä olisi ajettu paljaaksi.',
        6: 'Sillä jos vaimo ei verhoa päätään, leikatkoon hiuksensakin. Mutta koska on häpeäksi vaimolle leikata tai ajaa hiuksensa, peittäköön päänsä.',
        7: 'Miehen ei tule peittää päätään, koska hän on Jumalan kuva ja kunnia. Mutta vaimo on miehen kunnia.',
        8: 'Sillä mies ei ole vaimosta, vaan vaimo miehestä,',
        9: 'eikä miestä luotu vaimoa varten, vaan vaimo miestä varten.',
        10: 'Sen tähden vaimon tulee pitää päässään vallan merkkiä enkelien tähden.',
        11: 'Herrassa ei ole kuitenkaan vaimoa ilman miestä eikä miestä ilman vaimoa.',
        12: 'Sillä niin kuin vaimo on miehestä, samoin myös mies on vaimon kautta, mutta kaikki on Jumalasta.',
        13: 'Päättäkää itse: sopiiko vaimon rukoilla Jumalaa pää peittämättömänä?',
        14: 'Eikö itse luontokin opeta teille, että jos miehellä on pitkät hiukset, se on hänelle häpeäksi,',
        15: 'ja että jos vaimolla on pitkät hiukset, se on hänelle kunniaksi? Sillä ovathan hiukset annetut hänelle hunnuksi.',
        16: 'Mutta jos joku haluaa kiistellä, niin meillä ei ole sellaista tapaa eikä Jumalan seurakunnilla.',
        17: 'Mutta tätä käskiessäni en kiitä sitä, että kokoontumisenne ei tee teitä paremmiksi, vaan pahemmiksi.',
        18: 'Sillä ensiksikin olen kuullut, että kun kokoonnutte seurakunnassa, teillä on eriseuroja keskuudessanne, ja osittain sen uskonkin.',
        19: 'Täytyyhän teidän keskuudessanne olla puolueitakin, että koetuksen kestävät tulisivat ilmi.',
        20: 'Kun te näin kokoonnutte yhteen, se ei ole Herran illallisen nauttimista,',
        21: 'sillä syömään ruvettaessa kukin rientää ottamaan eteensä oman illallisensa, ja niin toinen on nälissään ja toinen juovuksissa.',
        22: 'Eikö teillä sitten ole muita huoneita, niissä syödäksenne ja juodaksenne? Vai halveksitteko Jumalan seurakuntaa ja tahdotteko häväistä niitä, joilla ei ole mitään? Mitä teille sanoisin? Tulisiko minun teitä tästä kiittää? En kiitä.',
        23: 'Sillä minä olen saanut Herralta sen, minkä myös olen teille tiedoksi antanut, että Herra Jeesus sinä yönä, jona hänet kavallettiin, otti leivän,',
        24: 'kiitti, mursi ja sanoi: "Tämä on minun ruumiini, teidän edestänne murrettu. Tehkää tämä minun muistokseni."',
        25: 'Samoin hän otti myös maljan aterian jälkeen ja sanoi: "Tämä malja on uusi liitto minun veressäni. Niin usein kuin te juotte, tehkää se minun muistokseni."',
        26: 'Sillä niin usein kuin te syötte tätä leipää ja juotte tämän maljan, te julistatte Herran kuolemaa, siihen asti kuin hän tulee.',
        27: 'Sen tähden se, joka kelvottomasti syö tätä leipää tai juo Herran maljan, on oleva syyllinen Herran ruumiiseen ja vereen.',
        28: 'Koetelkoon siis ihminen itsensä, ja niin syököön tätä leipää ja juokoon tästä maljasta,',
        29: 'sillä joka syö ja juo kelvottomasti erottamatta Herran ruumista muusta, syö ja juo itselleen tuomion.',
        30: 'Sen tähden onkin teidän joukossanne paljon heikkoja ja sairaita, ja monet ovat nukkuneet [pois].',
        31: 'Mutta jos tutkisimme itseämme, meitä ei tuomittaisi.',
        32: 'Mutta kun meitä tuomitaan, se on meille Herran kuritusta, ettei meitä maailman kanssa kadotukseen tuomittaisi.',
        33: 'Sen tähden, veljeni, kun kokoonnutte yhdessä aterioimaan, odottakaa toisianne.',
        34: 'Jos jollakulla on nälkä, syököön kotonaan, jotta ette kokoontuisi tuomioksenne. Muista seikoista säädän, kun tulen.',
    },
    12: {
        1: 'Mutta hengellisistä lahjoista, veljet, en tahdo pitää teitä tietämättöminä.',
        2: 'Te tiedätte, että kun olitte pakanoita, teitä ikään kuin ajamalla vietiin mykkien epäjumalien luo.',
        3: 'Sen tähden teen teille tiettäväksi, ettei kukaan, joka puhuu Jumalan Hengessä, sano: "Jeesus olkoon kirottu", ja ettei kukaan voi sanoa: "Jeesus on Herra", paitsi Pyhässä Hengessä.',
        4: 'Armolahjat ovat erilaisia, mutta Henki on sama.',
        5: 'Palvelusvirat ovat erilaisia, mutta Herra on sama.',
        6: 'Voimavaikutukset ovat erilaisia, mutta Jumala, joka kaiken kaikissa vaikuttaa, on sama.',
        7: 'Mutta kullekin annetaan Hengen ilmoitus yhteiseksi hyödyksi.',
        8: 'Niinpä toiselle annetaan Hengen kautta viisauden sanat, toiselle tiedon sanat saman Hengen mukaan,',
        9: 'toiselle usko samassa Hengessä, toiselle taas terveeksi tekemisen armolahjoja siinä yhdessä Hengessä,',
        10: 'toiselle voimateot, toiselle profetoiminen, toiselle henkien erottaminen, toiselle eri kielillä puhuminen, toiselle taas kielien selittäminen.',
        11: 'Mutta kaiken tämän vaikuttaa yksi ja sama Henki, jakaen kullekin erikseen, niin kuin tahtoo.',
        12: 'Sillä niin kuin ruumis on yksi ja siinä on monta jäsentä, mutta kaikki ruumiin jäsenet, vaikka niitä on monta, ovat yksi ruumis, niin on Kristuskin.',
        13: 'Sillä me olemme kaikki kastetut yhdessä Hengessä yhdeksi ruumiiksi, olimmepa juutalaisia tai kreikkalaisia, orjia tai vapaita, ja kaikki olemme saaneet juoda samaa Henkeä.',
        14: 'Sillä eihän ruumiskaan ole yksi jäsen, vaan monta.',
        15: 'Jos jalka sanoisi: "Koska en ole käsi, en kuulu ruumiiseen", se ei silti olisi ruumiiseen kuulumaton.',
        16: 'Jos korva sanoisi: "Koska en ole silmä, en kuulu ruumiiseen", se ei silti olisi ruumiiseen kuulumaton.',
        17: 'Jos koko ruumis olisi silmänä, missä sitten olisi kuulo? Jos taas kokonaan kuulona, missä silloin hajuaisti?',
        18: 'Mutta nyt Jumala on asettanut jäsenet, jokaisen niistä, ruumiiseen, niin kuin on tahtonut.',
        19: 'Vaan jos ne kaikki olisivat yhtenä jäsenenä, missä sitten olisi ruumis?',
        20: 'Nytpä onkin monta jäsentä, mutta vain yksi ruumis.',
        21: 'Silmä ei voi sanoa kädelle: "En tarvitse sinua", eikä myöskään pää jaloille: "En tarvitse teitä."',
        22: 'Päinvastoin ne ruumiin jäsenet, jotka näyttävät olevan heikompia, ovat välttämättömiä.',
        23: 'Ne ruumiin jäsenet, jotka meistä ovat vähemmän kunniakkaita, verhoamme sitä kunniallisemmin, ja niitä, joita häpeämme, sitä häveliäämmin peitämme,',
        24: 'mutta ne, joita emme häpeä, eivät sitä tarvitse. Mutta Jumala on liittänyt ruumiin yhteen niin, että antoi halvempiarvoiselle suuremman kunnian,',
        25: 'ettei ruumiissa olisi eripuraa, vaan että jäsenet pitäisivät yhtäläistä huolta toisistaan.',
        26: 'Jos yksi jäsen kärsii, kaikki jäsenet kärsivät sen kanssa, tai jos jollekulle jäsenelle annetaan kunnia, kaikki jäsenet iloitsevat sen kanssa.',
        27: 'Mutta te olette Kristuksen ruumis ja kukin osaltanne hänen jäseniään.',
        28: 'Niinpä Jumala asetti seurakuntaan ensiksi apostoleja, toiseksi profeettoja, kolmanneksi opettajia, sitten voimatekoja, sitten armolahjoja parantaa tauteja, avustaa, hallita ja puhua kielillä.',
        29: 'Eivät suinkaan kaikki ole apostoleja? Eivät kaikki profeettoja? Eivät kaikki opettajia? Eiväthän kaikki tee voimatekoja?',
        30: 'Eihän kaikilla ole parantamisen armolahjoja? Eiväthän kaikki puhu kielillä? Eiväthän kaikki niitä selitä?',
        31: 'Pyrkikää osallisiksi parhaimmista armolahjoista. Vielä minä osoitan teille suurenmoisen tien.',
    },
    13: {
        1: 'Jos puhuisin ihmisten ja enkelien kielillä, mutta minulla ei olisi rakkautta, olisin kumiseva vaski tai helisevä symbaali.',
        2: 'Jos minulla olisi profetia ja tietäisin kaikki salaisuudet ja kaiken tiedon, ja jos minulla olisi kaikki usko, että voisin siirtää vuoria, mutta minulla ei olisi rakkautta, en olisi mikään.',
        3: 'Jos jakelisin kaiken omaisuuteni, ja jos antaisin ruumiini poltettavaksi, mutta minulla ei olisi rakkautta, en siitä mitään hyötyisi.',
        4: 'Rakkaus on pitkämielinen, rakkaus on lempeä. Rakkaus ei kadehdi, ei kersku, ei pöyhkeile,',
        5: 'ei käyttäydy sopimattomasti, ei etsi omaansa, ei ärsyynny, ei muistele pahaa,',
        6: 'ei iloitse vääryydestä, vaan iloitsee yhdessä totuuden kanssa.',
        7: 'Kaikki se kestää, kaikki se uskoo, kaikki se toivoo, kaikki se kärsii.',
        8: 'Rakkaus ei koskaan häviä. Mutta profetiat loppuvat, ja kielet lakkaavat, ja tieto katoaa.',
        9: 'Sillä tietomme on osittaista, ja profetoimisemme on osittaista.',
        10: 'Mutta kun tulee se, mikä on täydellistä, katoaa se, mikä on osittaista.',
        11: 'Kun olin lapsi, puhuin kuin lapsi, minulla oli lapsen mieli, ja ajattelin kuin lapsi. Kun tulin mieheksi, hylkäsin sen, mikä lapsen on.',
        12: 'Sillä nyt näemme kuin kuvastimesta arvoituksen tavoin, mutta silloin kasvoista kasvoihin. Nyt minulla on osittainen tieto, mutta silloin minulla on oleva täydellinen tieto, kuten minut itsenikin täysin tunnetaan.',
        13: 'Niin pysyvät nyt usko, toivo ja rakkaus, nämä kolme, mutta suurin niistä on rakkaus.',
    },
    14: {
        1: 'Tavoitelkaa rakkautta ja olkaa innokkaita saamaan hengellisiä lahjoja, mutta etenkin profetoimaan.',
        2: 'Sillä kielellä puhuva ei puhu ihmisille, vaan Jumalalle. Häntä näet ei kuuntele kukaan, sillä hän puhuu salaisuuksia hengessä.',
        3: 'Mutta profetoiva puhuu ihmisille rakennukseksi, kehotukseksi ja lohdutukseksi.',
        4: 'Kielellä puhuva rakentaa itseään, mutta profetoiva rakentaa seurakuntaa.',
        5: 'Soisin teidän kaikkien puhuvan kielillä, mutta vielä mieluummin soisin teidän profetoivan. Sillä profetoiva on suurempi kuin kielillä puhuva, ellei tämä samalla selitä, niin että seurakunta rakentuu.',
        6: 'Jos nyt, veljet, tulisin luoksenne kielillä puhuen, minkä hyödyn sillä toisin, ellen puhuisi teille antaen ilmoituksen, tiedon, profetian tai opetuksen?',
        7: 'Niinhän on elottomien soittimienkin laita, huilujen tai sitrojen: kuinka tiedetään, mitä huilulla tai sitralla soitetaan, elleivät ne soi toisistaan erottuvin sävelin?',
        8: 'Niin ikään, jos torvi antaa epäselvän äänen, kuka valmistautuu taisteluun?',
        9: 'Samoin tekin: jos ette kielellänne saa esiin selvää puhetta, kuinka sellainen puhe tulee ymmärretyksi? Tehän puhutte tuuleen.',
        10: 'Maailmassa on monta eri kieltä, mutta mikään ei ole ilman merkitystä.',
        11: 'Mutta jos en tiedä sanojen merkitystä, olen puhujalle muukalainen, ja puhuja on minulle muukalainen.',
        12: 'Samoin tekin, koska tavoittelette hengellisiä lahjoja, pyrkikää seurakunnan rakennukseksi saamaan niitä runsaasti.',
        13: 'Sen tähden rukoilkoon se, joka puhuu kielellä, että hän osaisi selittää.',
        14: 'Sillä jos rukoilen kielellä puhuen, henkeni kyllä rukoilee, mutta ymmärrykseni on hedelmätön.',
        15: 'Kuinka siis on? Minun on rukoiltava hengelläni, mutta minun on rukoiltava myös ymmärrykselläni. Minun on veisattava kiitosta hengelläni, mutta minun on veisattava myös ymmärrykselläni.',
        16: 'Sillä jos ylistät Jumalaa hengessä, kuinka oppimattoman paikalla istuva saattaa sanoa "aamen" sinun kiitokseesi, koska hän ei tiedä, mitä sanot?',
        17: 'Sinä tosin kiität hyvin, mutta toinen ei siitä rakennu.',
        18: 'Kiitän Jumalaa, että puhun kielillä enemmän kuin kukaan teistä.',
        19: 'Mutta seurakunnassa tahdon mieluummin puhua viisi sanaa ymmärrykselläni opettaakseni muitakin kuin kymmenentuhatta sanaa kielillä.',
        20: 'Veljet, älkää olko lapsia ymmärrykseltänne, vaan pahuudessa olkaa lapsia, mutta ymmärrykseltä olkaa täysi-ikäisiä.',
        21: 'Laissa on kirjoitettuna: "Vieraskielisten kautta ja vieraiden huulilla olen puhuva tälle kansalle, eivätkä he sittenkään minua kuuntele, sanoo Herra."',
        22: 'Niinpä kielet eivät ole merkiksi uskoville, vaan uskosta osattomille, mutta profetia ei ole merkiksi uskosta osattomille, vaan uskoville.',
        23: 'Jos nyt koko seurakunta kokoontuisi yhteen ja kaikki puhuisivat kielillä ja sinne tulisi opetuksesta tai uskosta osattomia, eivätkö he sanoisi teidän olevan järjiltänne?',
        24: 'Mutta jos kaikki profetoisivat ja joku uskosta osaton tai oppimaton tulisi sisään, kaikki nuhtelisivat häntä ja kaikki tutkisivat häntä,',
        25: 'ja hänen sydämensä salaisuudet tulisivat ilmi, ja niin hän kasvoilleen langeten rukoilisi Jumalaa ja julistaisi, että Jumala totisesti on teissä.',
        26: 'Kuinka siis on, veljet? Kun tulette yhteen, on jokaisella jotakin annettavaa: kenellä on virsi, kenellä opetus, kenellä ilmoitus, kuka puhuu kielellä, kuka selittää. Kaikki tapahtukoon rakennukseksi.',
        27: 'Jos joku puhuu kielellä, puhukoon kullakin kertaa vain kaksi tai enintään kolme, ja yksi kerrallaan, ja yksi selittäköön.',
        28: 'Mutta jos ei ole selittäjää, niin olkoon vaiti seurakunnassa ja puhukoon itselleen ja Jumalalle.',
        29: 'Profeetoista saakoon kaksi tai kolme puhua, ja muut arvioikoot.',
        30: 'Mutta jos joku toinen siinä istuva saa ilmoituksen, vaietkoon ensimmäinen.',
        31: 'Sillä te voitte kaikki profetoida, toinen toisenne jälkeen, että kaikki saisivat opetusta ja kaikki kehotusta.',
        32: 'Profeettojen henget ovat profeetoille alistetut,',
        33: 'sillä Jumala ei ole epäjärjestyksen, vaan rauhan Jumala. Niin kuin kaikissa pyhien seurakunnissa,',
        34: 'naiset olkoot vaiti teidänkin seurakunnissanne, sillä heidän ei ole lupa puhua, vaan olkoot alamaisia, kuten lakikin sanoo.',
        35: 'Mutta jos he tahtovat oppia, kysykööt kotonaan omalta mieheltään, sillä häpeällistä on naisten puhua seurakunnassa.',
        36: 'Vai teistäkö Jumalan sana on lähtenyt? Vai ainoastaan teidänkö luoksenne se on tullut?',
        37: 'Jos joku luulee olevansa profeetta tai hengellinen, tietäköön, että mitä kirjoitan teille, se on Herran käsky.',
        38: 'Mutta jos joku ei sitä ymmärrä, olkoon ymmärtämättä.',
        39: 'Sen tähden, veljeni, harrastakaa profetoimista älkääkä estäkö kielillä puhumista.',
        40: 'Mutta kaikki tapahtukoon säädyllisesti ja järjestyksessä.',
    },
    15: {
        1: 'Veljet, ilmoitan teille sen evankeliumin, jonka teille julistin, jonka myös otitte vastaan ja jossa myös pysytte',
        2: 'ja jonka kautta myös pelastutte, jos pidätte siitä kiinni sen sanan mukaisena, jonka minä teille julistin, ellette ole turhaan uskoneet.',
        3: 'Sillä annoin teille ennen kaikkea tiedoksi sen, minkä itse olin saanut: että Kristus on kuollut meidän syntiemme tähden Kirjoitusten mukaan,',
        4: 'ja että hänet haudattiin ja että hän nousi kuolleista kolmantena päivänä Kirjoitusten mukaan,',
        5: 'ja että hän ilmestyi Keefaalle, sitten niille kahdelletoista.',
        6: 'Sen jälkeen hän ilmestyi yhdellä kertaa yli viidellesadalle veljelle, joista useimmat vielä nytkin ovat elossa, mutta muutamat ovat nukkuneet pois.',
        7: 'Sen jälkeen hän ilmestyi Jaakobille, sitten kaikille apostoleille.',
        8: 'Mutta kaikkein viimeiseksi hän ilmestyi minullekin, joka olen kuin keskosena syntynyt.',
        9: 'Sillä minä olen apostoleista vähäisin enkä ole sen arvoinen, että minua apostoliksi kutsutaan, koska vainosin Jumalan seurakuntaa.',
        10: 'Mutta Jumalan armosta olen se, mikä olen, eikä hänen armonsa minua kohtaan ole ollut turha, vaan enemmän kuin he kaikki olen työtä tehnyt, en kuitenkaan minä, vaan Jumalan armo, joka on kanssani.',
        11: 'Olinpa siis minä tai olivatpa nuo: tällä tavalla saarnaamme, ja näin te olette uskoneet.',
        12: 'Mutta jos Kristuksesta saarnataan, että hän on noussut kuolleista, kuinka eräät teistä sanovat, ettei kuolleiden ylösnousemusta ole?',
        13: 'Mutta jos ei ole kuolleiden ylösnousemusta, Kristuskaan ei ole noussut ylös.',
        14: 'Mutta jos Kristus ei ole noussut ylös, turha on silloin meidän saarnamme, turha myös teidän uskonne.',
        15: 'Silloin meidät myös havaitaan vääriksi Jumalan todistajiksi, koska olemme todistaneet Jumalaa vastaan, että hän herätti Kristuksen, jota hän ei ole herättänyt, jos kerran kuolleita ei herätetä.',
        16: 'Sillä jos kuolleita ei herätetä, ei Kristustakaan ole herätetty.',
        17: 'Mutta jos Kristusta ei ole herätetty, teidän uskonne on turha, ja te olette vielä synneissänne.',
        18: 'Silloinhan Kristuksessa nukkuneet olisivat kadotetut.',
        19: 'Jos olemme panneet toivomme Kristukseen ainoastaan tätä elämää koskien, olemme kaikkia muita ihmisiä kurjemmat.',
        20: 'Mutta nytpä Kristus on noussut kuolleista, ensi hedelmänä kuoloon nukkuneista.',
        21: 'Sillä koska kuolema on tullut ihmisen kautta, on myös kuolleiden ylösnousemus tullut ihmisen kautta.',
        22: 'Sillä niin kuin kaikki kuolevat Aadamissa, niin myös kaikki tehdään eläviksi Kristuksessa,',
        23: 'mutta jokainen vuorollaan: ensi hedelmänä Kristus, sitten Kristuksen omat hänen tulemuksessaan.',
        24: 'Sitten tulee loppu, kun hän antaa valtakunnan Jumalalle ja Isälle kukistettuaan kaiken hallituksen, kaiken vallan ja voiman.',
        25: 'Sillä hänen pitää hallita "siihen asti, kunnes hän on pannut kaikki viholliset jalkojensa alle."',
        26: 'Vihollisista viimeisenä kukistetaan kuolema.',
        27: 'Sillä: "kaikki hän on alistanut hänen jalkojensa alle." Mutta kun hän sanoo: "kaikki on alistettu", ei tietenkään ole alistettu se, joka on alistanut kaiken hänen alleen.',
        28: 'Kun kaikki on alistettu Pojan valtaan, silloin itse Poikakin alistetaan sen valtaan, joka on alistanut hänen valtaansa kaiken, että Jumala olisi kaikki kaikissa.',
        29: 'Mitä muuten ne, jotka kastattavat itsensä vainajien yläpuolella, sillä saavat aikaan? Jos kuolleet eivät herää, miksi nämä sitten kastattavat itsensä heidän yläpuolellaan?',
        30: 'Miksi mekin olemme joka hetki vaarassa?',
        31: 'Joka päivä olen kuoleman vaarassa, niin totta kuin te, veljet, olette minun kerskaukseni Kristuksessa Jeesuksessa, meidän Herrassamme.',
        32: 'Jos ihmisten tavoin olen taistellut petojen kanssa Efesossa, mitä hyötyä minulle siitä on? Jos kuolleita ei herätetä, niin: "syökäämme ja juokaamme, sillä huomenna kuolemme."',
        33: 'Älkää eksykö. "Huono seura hyvät tavat turmelee."',
        34: 'Raitistukaa oikealla tavalla älkääkä syntiä tehkö, sillä niitä on, joilla ei ole tietoa Jumalasta. Teidän häpeäksenne tämän sanon.',
        35: 'Mutta joku ehkä kysyy: "Millä tavoin kuolleet nousevat ylös, ja millaisessa ruumiissa he tulevat?"',
        36: 'Sinä typerä, se, minkä kylvät, ei virkoa eloon, ellei se kuole!',
        37: 'Kun kylvät, et kylvä koko tulevaa ruumista [kasvia], vaan pelkän jyvän, vehnän jyvän tai muun minkä tahansa.',
        38: 'Mutta Jumala antaa sille ruumiin [varren], sellaisen kuin tahtoo, ja kullekin siemenelle sen oman ruumiin [varren].',
        39: 'Ei kaikki liha ole samaa lihaa, vaan toista on ihmisten, toista taas karjan liha, toista on lintujen liha, toista kalojen.',
        40: 'On taivaallisia ruumiita [taivaankappaleita] ja maallisia ruumiita. Mutta toinen on taivaallisten kirkkaus, toinen taas maanpäällisten.',
        41: 'Toinen on auringon kirkkaus, toinen kuun kirkkaus ja toinen tähtien kirkkaus, ja toinen tähti eroaa toisesta kirkkaudessa.',
        42: 'Samalla tavalla on myös kuolleiden ylösnousemus: kylvetään katoavaisuudessa, nousee katoamattomuudessa;',
        43: 'kylvetään häpeässä, nousee kunniassa; kylvetään heikkoudessa, nousee voimassa;',
        44: 'kylvetään sielullinen ruumis, nousee hengellinen ruumis. Jos kerran on sielullinen ruumis, on myös hengellinen.',
        45: 'Näinhän on myös kirjoitettu: "Ensimmäisestä ihmisestä, Aadamista, tuli elävä sielu", viimeisestä Aadamista eläväksi tekevä henki.',
        46: 'Mutta mikä on hengellistä, se ei ole ensimmäinen, vaan se, mikä on sielullista, on ensimmäinen. Sitten on se, mikä on hengellistä.',
        47: 'Ensimmäinen ihminen oli maasta, maan tomusta, toinen ihminen, Herra, on taivaasta.',
        48: 'Millaista tomu on, sellaisia ovat myös ne, jotka ovat tomusta, ja millainen taivaallinen on, sellaisia ovat myös taivaalliset.',
        49: 'Niin kuin olemme kantaneet itsessämme tomun kuvaa, tulemme myös kantamaan itsessämme taivaallisen kuvaa.',
        50: 'Mutta tämän sanon, veljet, ettei liha ja veri voi periä Jumalan valtakuntaa, eikä katoavaisuus peri katoamattomuutta.',
        51: 'Katso, sanon teille salaisuuden: emme kaikki kuolemaan nuku, mutta kaikki muutumme,',
        52: 'yhtäkkiä, silmänräpäyksessä, viimeisen torven soidessa. Sillä torvi soi, ja kuolleet nousevat katoamattomina, ja muutumme.',
        53: 'Sillä tämän katoavaisen pitää pukeutua katoamattomuuteen, ja tämän kuolevaisen pitää pukeutua kuolemattomuuteen.',
        54: 'Mutta kun tämä katoavainen pukeutuu katoamattomuuteen ja tämä kuolevainen pukeutuu kuolemattomuuteen, silloin toteutuu se sana, joka on kirjoitettu: "Kuolema on nielty voitossa."',
        55: '"Kuolema, missä on sinun piikkisi? Helvetti, missä on sinun voittosi?"',
        56: 'Mutta kuoleman piikki on synti, ja synnin voima on laki.',
        57: 'Mutta kiitos olkoon Jumalan, joka antaa meille voiton meidän Herramme Jeesuksen Kristuksen kautta!',
        58: 'Sen tähden, rakkaat veljeni, olkaa lujat, järkähtämättömät ja aina innokkaat Herran työssä tietäen, että vaivannäkönne ei ole turhaa Herrassa.',
    },
    16: {
        1: 'Mitä tulee keräykseen pyhiä varten, tehkää tekin samalla tavoin, kuin määräsin Galatian seurakunnille.',
        2: 'Viikon ensimmäisenä päivänä pankoon jokainen teistä kotonaan jotakin talteen menestymisensä mukaan, ettei keräyksiä tehtäisi vasta sitten, kun tulen.',
        3: 'Mutta kun olen saapunut, lähetän hyväksymänne henkilöt saatekirjeet mukanaan viemään rakkaudenlahjanne Jerusalemiin,',
        4: 'ja jos asia on sen arvoinen, että minäkin lähden, heidän tulee lähteä kanssani.',
        5: 'Tulen luoksenne kuljettuani läpi Makedonian, sillä kuljen Makedonian kautta.',
        6: 'Mutta teidän luonanne viivyn ehkä jonkin aikaa tai vietän talvenkin, että te sitten varustaisitte minut matkaan, minne matkustankin.',
        7: 'Sillä en tahdo nyt vain ohimennen käydä teitä katsomassa, toivon näet saavani viipyä luonanne jonkin aikaa, jos Herra sallii.',
        8: 'Mutta Efesossa viivyn helluntaihin asti,',
        9: 'sillä minulle on avautunut ovi suureen ja hedelmälliseen työhön, ja vastustajia on paljon.',
        10: 'Mutta jos Timoteus saapuu, katsokaa, että hän voi olla luonanne pelkäämättä, sillä Herran työtä hän tekee kuten minäkin.',
        11: 'Älköön siis kukaan häntä halveksiko, vaan varustakaa hänet rauhassa matkalle, että hän tulisi luokseni, sillä odotan häntä veljien kanssa.',
        12: 'Mitä veli Apolloon tulee, olen kovasti kehottanut häntä lähtemään veljien kanssa luoksenne. Mutta hän ei ole ollenkaan halukas lähtemään nyt, vaan tulee, kun hänelle sopii.',
        13: 'Valvokaa, pysykää lujina uskossa, olkaa miehuulliset, olkaa vahvat.',
        14: 'Kaikki, mitä teette, tapahtukoon rakkaudessa.',
        15: 'Mutta kehotan teitä, veljet: te tunnette Stefanaan perhekunnan ja tiedätte, että se on Akaian ensi hedelmä ja että he ovat antautuneet pyhien palvelukseen.',
        16: 'Olkaa tekin kuuliaisia heidän kaltaisilleen ja jokaiselle, joka tekee työtä ja näkee vaivaa heidän kanssaan.',
        17: 'Iloitsen Stefanaan, Fortunatoksen ja Akaikoksen tulosta tänne, koska he korvaavat teidän poissaolonne.',
        18: 'He ovat virkistäneet minun henkeäni niin kuin teidänkin. Antakaa siis sellaisille tunnustusta.',
        19: 'Aasian seurakunnat tervehtivät teitä. Monet tervehdykset Herrassa lähettävät teille Akylas ja Priskilla sekä heidän kodissaan kokoontuva seurakunta.',
        20: 'Kaikki veljet lähettävät teille tervehdyksen. Tervehtikää toisianne pyhällä suudelmalla.',
        21: 'Tervehdys minulta, Paavalilta, omakätisesti.',
        22: 'Jos joku ei rakasta Herraa Kristusta, hän olkoon kirottu! Maran ata.',
        23: 'Herran Jeesuksen armo olkoon kanssanne.',
        24: 'Rakkauteni on teidän kaikkien kanssa Kristuksessa Jeesuksessa.',
    },
}
